def pil_pump_probe_on '{
  # pil_on [list of detector indices from 0 to 9]
  #   Enable one or more pilati to snap images during scan.
  #   Active detectors are maintained as an associative array PIL["det_on"]

  local i j nsplit det_list det_array[]

  if ($# == 0) {
    for (i in PIL["det_setup"])
       PIL["det_on"][i] = i
    }
  else {
    nsplit = split("$*", det_array)
    for (i in det_array)
      if (det_array[i] in PIL["det_setup"])
        PIL["det_on"][det_array[i]] = int(det_array[i])
  }

  # Set up SRS Delay Generator to repeat MCS_CLK0 pulses with 0.1 ms square pulses.
  # Note: this is not OK for the Xspress detectors, where the trigger also acts
  # gate.
  # sync_repeat

  PIL["n_on"] = 0
  for (i in PIL["det_on"])
    PIL["n_on"]++

  if (PIL["n_on"] > 0) {
    cdef("", "", PIL_CDEF_LABEL, "delete")
    cdef("user_postscan_head", "_pil_scan_head_pump_probe; opens; ", PIL_CDEF_LABEL, 0x10)
    cdef("user_precount", "_pil_precount_pump_probe;",  PIL_CDEF_LABEL, 0x10)
    cdef("user_flyscan_pre_run", "_pil_precount_pump_probe;",  PIL_CDEF_LABEL, 0x10)
    # The following line goes alongside,  "WaitForPlugins==Yes" in pil_setup
    # And note: can interfere with "uct" and other functions that update
    # counters during a ct.
    # The following is nice for internal triggering; not so much for Mult. Trigger
    cdef("user_getcounts", "sleep(2); _pil_getcounts;", PIL_CDEF_LABEL, 0x10)
    cdef("user_scan_tail", "_pil_scan_tail_pump_probe; closes; ", PIL_CDEF_LABEL, 0x10)
  }

  pil_show

  pico_filter_on

  QM2_PUMP_PROBE_MODE = 1



}'

def pil_pump_probe_off '{
  local i nsplit det_array

  if ($# == 0) {
    for (i in PIL["det_setup"])
      delete PIL["det_on"][i]
    PIL["n_on"] = 0
    }
  else {
    nsplit = split("$*", det_array)
    for (i in det_array)
      if (det_array[i] in PIL["det_on"])
        delete PIL["det_on"][det_array[i]]
    PIL["n_on"] = 0
    for (i in PIL["det_on"])
      PIL["n_on"]++
    }

  if (PIL["n_on"] == 0)
    cdef("", "", PIL_CDEF_LABEL, "delete")

  pil_show
  if (QM2_PUMP_PROBE_MODE){
    pil_im_set(i, "TriggerMode", PIL[i]["trigger"])
    pil_im_set(i, "ImageMode", "Single")
    pil_im_set(i, "NumExposures", 1)
  }

  pico_filter_off
  QM2_PUMP_PROBE_MODE = 0



}'

def _pil_scan_head_pump_probe '{
  local n_exposures, n_images

  _pil_halt
  sleep(0.5)
  if (PIL_DEBUG)
	  print "After _pil_halt; start _pil_wait_idle"
  _pil_wait_idle

  if (PIL_DEBUG)
	 print "After first _pil_wait_idle"
   _pil_wait_idle
    cdef("cleanup_once", "_pil_cleanup;", PIL_CDEF_LABEL)

   _pil_file_setpath

  # NOTE: Sept 2020: learned that _pil_scan_head should happen BEFORE fly_postscan_head to
  # avoid missing the first trigger.
  if  (PIL_DEBUG)
    prdef  user_postscan_head

  PIL_INT_TRIG = 0
  for (i in PIL["det_on"])
      if (PIL[i]["trigger"] == "Internal") {
         #pil_settrig  "Internal"
         PIL_INT_TRIG = 1
         break
      }
  if (_stype  & scanType_MeshScan)
    PIL_SCAN_DIMS = 2
  else
    PIL_SCAN_DIMS = 1


  if (_stype & scanType_Fly) {
    PIL_FLYMODE = 1

    n_images = _fly_intervals + 1
  } else {
    PIL_FLYMODE = 0
    if (PIL_INT_TRIG) {
       n_images = 1
    } if (QM2_PUMP_PROBE_MODE){
      n_exposures = PUMP_PROBE_N_EXP_FRAME
      n_images = _n1
    } else{
      n_images = _n1
    }

  }

  # time per point calc for native spec fly scan
  if (PIL_FLYMODE){
    #_dwell  =  _ctime/_fly_intervals
    _dwell = FLY_dwell 
    cdef("user_pregetcounts", "", PIL_CDEF_LABEL, "delete")
  } else {
    _dwell  = _ctime
    cdef("user_getcounts", "_pil_getcounts;", PIL_CDEF_LABEL, 0x10)
  }

  # Pulse lengths for external devies are set in
  # fly_prep_clk0_repeat in spec_flyscan_cust_v6, and customized by altering
  # the variable FLY_PULSE_DOWNTIME. This is the detector overhead, e.g. 0.002
  # seconds (or less) for Eiger, and about 0.01-0.02 for Pilati.

  print "About to set FLY_PULSE_DOWNTIME TO" PIL_OVERHEAD
  PIL_SAVE_PULSE_DOWNTIME = FLY_PULSE_DOWNTIME
  FLY_PULSE_DOWNTIME = PIL_OVERHEAD

  for (i in PIL["det_on"]) {
    if (QM2_PUMP_PROBE_MODE){
      #PIL_INT_TRIG = 0
      pil_im_set(i, "TriggerMode", "Ext. Enable")
      #pil_im_set(i, "TriggerMode", "Mult. Trigger")
      pil_im_set(i, "ImageMode", "Single")
      pil_im_set(i, "AcquireTime", _dwell-PIL_OVERHEAD)
      pil_im_set(i, "AcquirePeriod", _dwell) #+ PIL_OVERHEAD)
      pil_im_set(i, "NumImages", n_images)
      pil_im_set(i, "NumExposures", n_exposures)
    }

    if (PIL_H5) {
      pil_set(i, "HDF1:NumExtraDims", 0)
      pil_set(i, "HDF1:ExtraDimSizeN", n_images)
      pil_set(i, "HDF1:FileWriteMode", "Capture")
      pil_set(i, "HDF1:AutoSave", "Yes")
    }
  }
    pil_show
}'

