def _mca_startcount() '{
    local i ioc visited[]

    for (i in MCA_PV) {
        if (!(MCA_SMODE[i]))
           continue

        ioc = MCA_PV[i]
        if (!(ioc in visited)) {
            visited[ioc] = 1

            epics_put(sprintf(\"%s.PRTM\", ioc), 0)
            epics_put(sprintf(\"%s.PLTM\", ioc), 0)
            epics_put(sprintf(\"%s.ERST\", ioc), 1)
            while (!(epics_get(sprintf("%s.ACQG", ioc), "short"))) {
                sleep(0.001)
            }
        }
    }
}'

def _mca_stopcount() '{
    local i visited[] REPEAT_STOP REPEAT_CTR

    #sleep(.1)
    for(i in MCA_PV) {
        if (!(MCA_SMODE[i]))
           continue
        wait(2); sleep(.05)
        ioc = MCA_PV[i]
        if (!(ioc in visited)) {
            visited[ioc] = 1
			REPEAT_STOP = 1
			REPEAT_CTR = 0
			while(REPEAT_STOP) {
            	epics_put(sprintf(\"%s.STOP\", ioc), 1, 2)
				if (EPICS_ERR != 0){
					print "In stopcount: EPICS_ERR = " EPICS_ERR
					#print "EPICS_ERR_MSG = " EPICS_ERROR_MSG
					sleep(0.5)
					epics_par(sprintf(\"%s\", ioc), "refresh") 
					REPEAT_CTR++
				} else {
					REPEAT_STOP = 0
				}
			}
        }
    }
    # make sure each IOC has stopped acquiring
    for(i in MCA_PV) {
        if (!(MCA_SMODE[i]))
           continue

        ioc = MCA_PV[i]
        if (!(ioc in visited)) {
            visited[ioc] = 1
            while (epics_get(sprintf("%s.ACQG", ioc), "short")) {
                # give the IOC more time to populate the records
                sleep(0.001)
            }
        }
    }
}'

def _mca_getcounts() '{
    local i ioc visited[]

    # make sure each IOC has populated the records
    for(i in MCA_PV) {
        if (!(MCA_SMODE[i]))
           continue

        ioc = MCA_PV[i]
        if (!(ioc in visited)) {
            visited[ioc] = 1
            while (epics_get(sprintf("%s.RDNG", ioc), "short")) {
                 # give the IOC more time to populate the records
                 sleep(0.01)
             }
        }
    }

    for (i in MCA_PV) {
        if (!(MCA_SMODE[i]))
           continue

        local A_name

        if (MCA_SMODE[i]) {
            A_name = sprintf("mcadat_%s", i)
            if (COUNT_TIME) {
                @A_name[1] = epics_get(MCA_PV[i])
            } else {
                array_op("fill", @A_name[:][1], 0)
            }
        }
    }
}'

