    #cmd[i++] = "smua.trigger.source.action = smua.ENABLE"


    #for (i in cmd){
    #    k2600_send(cmd[i])
    #}


    # manual loop sweep
    if (end > start)
        dir = 1
    else
        dir = -1

    while(start < end){
        k2600_von(start)
        sleep(delay)
        start += (step * dir)
    }
    k2600_von(end)


}'

